    /** A count-free, immutable explanation for a visible planner marker. */
    default Optional<NeededItemDetail> detailFor(int itemId)
    {
        return Optional.empty();
    }
}

package com.stashledger.items;

import com.stashledger.model.BuildStatus;
import com.stashledger.model.ContentsStatus;
import com.stashledger.model.StashEntry;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.client.game.ItemManager;

/**
 * Creates a thread-safe snapshot of source-declared equipment candidates for
 * every STASH that is not already built and filled. This is intentionally a
 * planner marker, never an item-count or equipment-fulfillment evaluator.
 */
public final class NeededItemProvider implements NeededItemLookup
{
    private final IntUnaryOperator canonicalize;
    private final Map<String, Set<Integer>> requirementIdsByStash;
    /** One volatile reference prevents a render from mixing eligibility and hover detail epochs. */
    private volatile Map<Integer, NeededItemDetail> detailsByItemId = Map.of();

    public NeededItemProvider(ItemManager itemManager, Map<String, Set<Integer>> requirementIdsByStash)
    {
        this(itemManager::canonicalize, requirementIdsByStash);
    }

    NeededItemProvider(IntUnaryOperator canonicalize, Map<String, Set<Integer>> requirementIdsByStash)
    {
        this.canonicalize = canonicalize;
        Map<String, Set<Integer>> copy = new HashMap<>();
        for (Map.Entry<String, Set<Integer>> entry : requirementIdsByStash.entrySet())
        {
            copy.put(entry.getKey(), Set.copyOf(entry.getValue()));
        }
        this.requirementIdsByStash = Map.copyOf(copy);
    }

    /** Replaces the snapshot atomically; callers may supply any account's full ledger snapshot. */
    public void refresh(List<StashEntry> entries)
    {
        refresh(entries, null);
    }

    /**
     * Replaces the snapshot atomically. A focus ID intentionally narrows the
     * plan to exactly one built, confirmed-empty unit; an invalid focus means
     * no candidates rather than an ambiguous return to the global plan.
     */
    public void refresh(List<StashEntry> entries, String fillStashId)
    {
        Map<Integer, Map<String, StashEntry>> entriesByItemId = new HashMap<>();
        boolean focused = fillStashId != null;
        if (entries != null)
        {
            for (StashEntry entry : entries)
            {
                if (entry == null || (focused ? !isFillableFocus(entry, fillStashId) : isComplete(entry)))
                {
                    continue;
                }
                for (int requirementId : requirementIdsByStash.getOrDefault(entry.getDefinition().getId(), Set.of()))
                {
                    int canonicalId = canonicalize.applyAsInt(requirementId);
                    entriesByItemId.computeIfAbsent(canonicalId, unused -> new LinkedHashMap<>())
                        .put(entry.getDefinition().getId(), entry);
                }
            }
        }
        Map<Integer, NeededItemDetail> next = new HashMap<>();
        for (Map.Entry<Integer, Map<String, StashEntry>> entry : entriesByItemId.entrySet())
        {
            next.put(entry.getKey(), new NeededItemDetail(entry.getKey(), List.copyOf(entry.getValue().values()), focused));
        }
        detailsByItemId = Map.copyOf(next);
    }

    public void clear()
    {
        detailsByItemId = Map.of();
    }

    @Override
    public boolean isNeeded(int itemId)
    {
        Map<Integer, NeededItemDetail> snapshot = detailsByItemId;
        return !snapshot.isEmpty() && snapshot.containsKey(canonicalize.applyAsInt(itemId));
    }

    @Override
    public Optional<NeededItemDetail> detailFor(int itemId)
    {
        Map<Integer, NeededItemDetail> snapshot = detailsByItemId;
        if (snapshot.isEmpty())
        {
            return Optional.empty();
        }
        int canonicalId = canonicalize.applyAsInt(itemId);
        return Optional.ofNullable(snapshot.get(canonicalId));
    }

    private static boolean isComplete(StashEntry entry)
    {
        return entry.getBuildStatus() == BuildStatus.BUILT
            && entry.getContentsStatus() == ContentsStatus.FILLED;
    }

    private static boolean isFillableFocus(StashEntry entry, String fillStashId)
    {
        return fillStashId.equals(entry.getDefinition().getId())
            && entry.getBuildStatus() == BuildStatus.BUILT
            && entry.getContentsStatus() == ContentsStatus.EMPTY;
    }
}

package com.stashledger.items;

import com.stashledger.StashLedgerConfig;
import com.stashledger.model.StashTier;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Renders passive, count-free planner markers in inventory, bank, and equipment widgets. */
public final class StashNeededItemOverlay extends WidgetItemOverlay
{
    static final Color PLANNER_COLOR = new Color(230, 189, 121, 220);
    private final NeededItemLookup neededItems;
    private final Client client;
    private final ItemManager itemManager;
    private final TooltipManager tooltipManager;
    private final StashLedgerConfig config;

    public StashNeededItemOverlay(NeededItemLookup neededItems, Client client, ItemManager itemManager,
                                  TooltipManager tooltipManager, StashLedgerConfig config)
    {
        this.neededItems = Objects.requireNonNull(neededItems);
        this.client = Objects.requireNonNull(client);
        this.itemManager = Objects.requireNonNull(itemManager);
        this.tooltipManager = Objects.requireNonNull(tooltipManager);
        this.config = Objects.requireNonNull(config);
        showOnInventory();
        showOnBank();
        showOnEquipment();
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (!neededItems.isNeeded(itemId))
        {
            return;
        }
        Optional<NeededItemDetail> detail = neededItems.detailFor(itemId);
        Rectangle bounds = widgetItem.getCanvasBounds();
        if (config.highlightStyle() == ItemHighlightStyle.OUTLINE)
        {
            BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), PLANNER_COLOR);
            if (outline != null)
            {
                graphics.drawImage(outline, bounds.x, bounds.y, null);
            }
        }
        else
        {
            drawDots(graphics, bounds, detail.orElse(null));
        }
        if (detail.isPresent())
        {
            addTooltipIfHovered(detail.get(), widgetItem, bounds);
        }
    }

    private void drawDots(Graphics2D graphics, Rectangle bounds, NeededItemDetail detail)
    {
        List<StashTier> tiers = detail == null ? List.of() : detail.getTiers();
        if (config.dotColorMode() != DotColorMode.CLUE_TIER || tiers.isEmpty())
        {
            drawDot(graphics, bounds, configuredColor(config.singleDotColor()));
            return;
        }

        int diameter = dotDiameter(bounds);
        if (diameter < 3) { return; }
        int gap = 1;
        int columns = Math.min(3, tiers.size());
        int width = columns * diameter + (columns - 1) * gap;
        int rows = (tiers.size() + 2) / 3;
        int height = rows * diameter + (rows - 1) * gap;
        int x = bounds.x + bounds.width - width - 2;
        int y = bounds.y + 2;
        if (x < bounds.x || y + height > bounds.y + bounds.height) { return; }
        for (int index = 0; index < tiers.size(); index++)
        {
            int dotX = x + (index % 3) * (diameter + gap);
            int dotY = y + (index / 3) * (diameter + gap);
            graphics.setColor(tierColor(tiers.get(index)));
            graphics.fillOval(dotX, dotY, diameter, diameter);
        }
    }

    private static int dotDiameter(Rectangle bounds)
    {
        int diameter = Math.min(7, Math.min(bounds.width, bounds.height) / 4);
        return diameter >= 3 ? diameter : 0;
    }

    private static void drawDot(Graphics2D graphics, Rectangle bounds, Color color)
    {
        int diameter = dotDiameter(bounds);
        if (diameter < 3) { return; }
        int x = bounds.x + bounds.width - diameter - 2;
        int y = bounds.y + 2;
        if (x < bounds.x || y + diameter > bounds.y + bounds.height) { return; }
        graphics.setColor(color);
        graphics.fillOval(x, y, diameter, diameter);
    }

    private Color tierColor(StashTier tier)
    {
        if (tier == null) { return PLANNER_COLOR; }
        switch (tier)
        {
            case BEGINNER: return configuredColor(config.beginnerDotColor());
            case EASY: return configuredColor(config.easyDotColor());
            case MEDIUM: return configuredColor(config.mediumDotColor());
            case HARD: return configuredColor(config.hardDotColor());
            case ELITE: return configuredColor(config.eliteDotColor());
            case MASTER: return configuredColor(config.masterDotColor());
            default: return PLANNER_COLOR;
        }
    }

    private static Color configuredColor(Color configured)
    {
        return configured == null ? PLANNER_COLOR : configured;
    }

    private void addTooltipIfHovered(NeededItemDetail detail, WidgetItem widgetItem, Rectangle bounds)
    {
        if (!config.itemHoverDetails() || client.isMenuOpen() || client.isDraggingWidget()
            || widgetItem.getDraggingCanvasBounds() != null)
        {
            return;
        }
        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null || !bounds.contains(mouse.getX(), mouse.getY()))
        {
            return;
        }
        tooltipManager.add(new Tooltip(tooltipText(detail)));
    }

    static String tooltipText(NeededItemDetail detail)
    {
        StringBuilder text = new StringBuilder(detail.isFocused() ? "<col=E6BD79>Fill this STASH</col><br>" : "<col=E6BD79>STASH planner</col><br>");
        if (!detail.getTiers().isEmpty())
        {
            text.append("Tiers: ");
            for (int index = 0; index < detail.getTiers().size(); index++)
            {
                if (index > 0) { text.append(", "); }
                text.append(detail.getTiers().get(index).getLabel());
            }
            text.append("<br>");
        }
        List<com.stashledger.model.StashEntry> stashes = detail.getStashes();
        int visible = Math.min(6, stashes.size());
        for (int index = 0; index < visible; index++)
        {
            com.stashledger.model.StashEntry stash = stashes.get(index);
            text.append(escape(stash.getDefinition().getName())).append(" - ")
                .append(escape(stash.getDefinition().getTier().getLabel())).append(" - ")
                .append(escape(state(stash))).append("<br>");
        }
        if (stashes.size() > visible)
        {
            text.append('+').append(stashes.size() - visible).append(" more locations");
        }
        return text.toString();
    }

    private static String state(com.stashledger.model.StashEntry entry)
    {
        if (entry.getBuildStatus() != com.stashledger.model.BuildStatus.BUILT)
        {
            return entry.getBuildStatus() == com.stashledger.model.BuildStatus.NOT_BUILT ? "not built" : "construction unknown";
        }
        switch (entry.getContentsStatus())
        {
            case FILLED: return "filled";
            case EMPTY: return "empty";
            default: return "contents unknown";
        }
    }

    private static String escape(String value)
    {
        return value.replace("<", "[").replace(">", "]");
    }
}

package com.stashledger.map;

import com.stashledger.model.BuildStatus;
import com.stashledger.model.ContentsStatus;
import com.stashledger.model.StashDefinition;
import com.stashledger.model.StashEntry;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;

/** Owns only the ledger's overview markers; call from the client thread. */
public final class StashMapMarkers
{
    private final WorldMapPointManager manager;
    private final List<WorldMapPoint> points = new ArrayList<>();
    private Map<String, String> visibleStates = Map.of();

    public StashMapMarkers(WorldMapPointManager manager)
    {
        this.manager = manager;
    }

    public void refresh(List<StashEntry> entries, boolean enabled, boolean hideFilled)
    {
        Map<String, String> next = new LinkedHashMap<>();
        if (enabled)
        {
            for (StashEntry entry : entries)
            {
                if (hideFilled && entry.getContentsStatus() == ContentsStatus.FILLED) { continue; }
                next.put(entry.getDefinition().getId(), status(entry));
            }
        }
        if (next.equals(visibleStates)) { return; }
        clear();
        for (StashEntry entry : entries)
        {
            StashDefinition definition = entry.getDefinition();
            if (!next.containsKey(definition.getId())) { continue; }
            for (WorldPoint location : definition.getWorldPoints())
            {
                WorldMapPoint point = new WorldMapPoint(location, icon(entry));
                point.setName("STASH: " + definition.getName());
                point.setTooltip(definition.getTier().getLabel() + " STASH: " + definition.getName()
                    + " | " + next.get(definition.getId()));
                point.setJumpOnClick(true);
                points.add(point);
                manager.add(point);
            }
        }
        visibleStates = next;
    }

    public void clear()
    {
        for (WorldMapPoint point : points) { manager.remove(point); }
        points.clear();
        visibleStates = Map.of();
    }

    private static String status(StashEntry entry)
    {
        if (entry.getBuildStatus() == BuildStatus.UNKNOWN) { return "Construction unknown"; }
        if (entry.getBuildStatus() == BuildStatus.NOT_BUILT) { return "Not built"; }
        switch (entry.getContentsStatus())
        {
            case FILLED: return "Built, filled";
            case EMPTY: return "Built, empty";
            default: return "Built, contents unknown";
        }
    }

    private static BufferedImage icon(StashEntry entry)
    {
        Color color;
        if (entry.getBuildStatus() == BuildStatus.UNKNOWN) { color = new Color(159, 164, 173); }
        else if (entry.getBuildStatus() == BuildStatus.NOT_BUILT) { color = new Color(220, 116, 105); }
        else if (entry.getContentsStatus() == ContentsStatus.FILLED) { color = new Color(133, 187, 150); }
        else if (entry.getContentsStatus() == ContentsStatus.EMPTY) { color = new Color(230, 189, 121); }
        else { color = new Color(130, 167, 207); }
        BufferedImage image = new BufferedImage(12, 12, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(new Color(25, 28, 33)); graphics.fillOval(0, 0, 12, 12);
        graphics.setColor(color); graphics.fillOval(2, 2, 8, 8);
        graphics.dispose();
        return image;
    }
}

