package com.stashledger.state;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.stashledger.model.BuildStatus;
import com.stashledger.model.ContentsStatus;
import com.stashledger.model.StashDefinition;
import com.stashledger.model.StashEntry;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** One profile's state, confined to the client thread. Only confirmed contents and pins persist. */
public final class LedgerState
{
    private final List<StashDefinition> definitions;
    private final Map<String, BuildStatus> builds = new HashMap<>();
    private final Map<String, ContentsStatus> contents = new HashMap<>();
    private final Map<String, Boolean> pins = new HashMap<>();

    public LedgerState(List<StashDefinition> definitions)
    {
        this.definitions = Collections.unmodifiableList(new ArrayList<>(definitions));
        definitions.forEach(d -> builds.put(d.getId(), BuildStatus.UNKNOWN));
    }

    /** Strict transactional parsing prevents a malformed save from partially replacing state. */
    public void load(String json)
    {
        Map<String, ContentsStatus> loadedContents = new HashMap<>();
        Map<String, Boolean> loadedPins = new HashMap<>();
        if (json != null && !json.trim().isEmpty())
        {
            JsonObject root = new JsonParser().parse(json).getAsJsonObject();
            if (!root.has("version") || root.get("version").getAsInt() != 1 || !root.has("units"))
            {
                throw new IllegalArgumentException("Unsupported STASH Ledger save format");
            }
            for (Map.Entry<String, JsonElement> entry : root.getAsJsonObject("units").entrySet())
            {
                if (!builds.containsKey(entry.getKey())) { continue; }
                JsonObject value = entry.getValue().getAsJsonObject();
                if (value.has("contents"))
                {
                    loadedContents.put(entry.getKey(), ContentsStatus.valueOf(value.get("contents").getAsString()));
                }
                if (value.has("pinned"))
                {
                    if (!value.get("pinned").isJsonPrimitive() || !value.getAsJsonPrimitive("pinned").isBoolean())
                    {
                        throw new IllegalArgumentException("Invalid shortlist state");
                    }
                    loadedPins.put(entry.getKey(), value.get("pinned").getAsBoolean());
                }
            }
        }
        contents.clear(); contents.putAll(loadedContents);
        pins.clear(); pins.putAll(loadedPins);
        builds.replaceAll((id, status) -> BuildStatus.UNKNOWN);
    }

    public String serialize()
    {
        JsonObject root = new JsonObject();
        root.addProperty("version", 1);
        JsonObject units = new JsonObject();
        for (StashDefinition definition : definitions)
        {
            String id = definition.getId();
            ContentsStatus content = contents.getOrDefault(id, ContentsStatus.UNKNOWN);
            boolean pinned = pins.getOrDefault(id, false);
            if (content == ContentsStatus.UNKNOWN && !pinned) { continue; }
            JsonObject value = new JsonObject();
            value.addProperty("contents", content.name());
            value.addProperty("pinned", pinned);
            units.add(id, value);
        }
        root.add("units", units);
        return root.toString();
    }

    public void applyBuildScan(Map<String, BuildStatus> scan)
    {
        for (StashDefinition d : definitions)
        {
            BuildStatus status = scan.getOrDefault(d.getId(), BuildStatus.UNKNOWN);
            builds.put(d.getId(), status);
            if (status == BuildStatus.NOT_BUILT) { contents.remove(d.getId()); }
        }
    }

    public boolean markContents(String id, ContentsStatus status)
    {
        if (status == null || builds.get(id) != BuildStatus.BUILT) { return false; }
        contents.put(id, status);
        return true;
    }

    public boolean togglePinned(String id)
    {
        if (!builds.containsKey(id)) { return false; }
        pins.put(id, !pins.getOrDefault(id, false));
        return true;
    }

    public List<StashEntry> snapshot()
    {
        List<StashEntry> result = new ArrayList<>();
        for (StashDefinition d : definitions)
        {
            result.add(new StashEntry(d, builds.get(d.getId()),
                contents.getOrDefault(d.getId(), ContentsStatus.UNKNOWN), pins.getOrDefault(d.getId(), false)));
        }
        return Collections.unmodifiableList(result);
    }

    public Map<String, BuildStatus> buildSnapshot()
    {
        return Collections.unmodifiableMap(new LinkedHashMap<>(builds));
    }
}

package com.stashledger.tracking;

import com.stashledger.model.BuildStatus;
import com.stashledger.model.StashDefinition;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;

/**
 * Reads the client-owned construction state for the supplied STASH catalog.
 *
 * <p>The caller must invoke this on RuneLite's client thread. This class follows
 * the public Watson script contract rather than inferring state from objects or
 * chat messages. A script failure deliberately escapes, so callers retain their
 * last verified snapshot instead of replacing it with guesses.</p>
 */
public final class BuildScanner
{
    private BuildScanner()
    {
    }

    public static Map<String, BuildStatus> scan(Client client, List<StashDefinition> definitions)
    {
        Objects.requireNonNull(client, "client");
        Objects.requireNonNull(definitions, "definitions");

        Map<String, BuildStatus> result = new LinkedHashMap<>();
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            for (StashDefinition definition : definitions)
            {
                result.put(definition.getId(), BuildStatus.UNKNOWN);
            }
            return Collections.unmodifiableMap(result);
        }

        for (StashDefinition definition : definitions)
        {
            client.runScript(ScriptID.WATSON_STASH_UNIT_CHECK, definition.getObjectId(), 0, 0, 0);
            int[] intStack = client.getIntStack();
            BuildStatus status = intStack != null && intStack.length > 0
                ? toBuildStatus(intStack[0])
                : BuildStatus.UNKNOWN;
            result.put(definition.getId(), status);
        }
        return Collections.unmodifiableMap(result);
    }

    private static BuildStatus toBuildStatus(int scriptValue)
    {
        if (scriptValue == 0)
        {
            return BuildStatus.NOT_BUILT;
        }
        if (scriptValue == 1)
        {
            return BuildStatus.BUILT;
        }
        return BuildStatus.UNKNOWN;
    }
}

package com.stashledger.tracking;

import com.stashledger.model.ContentsStatus;
import com.stashledger.model.StashDefinition;
import java.util.Objects;
import java.util.Optional;

/**
 * Correlates one explicitly verified STASH Search interaction with RuneLite's
 * exact deposit or withdraw success message.
 *
 * <p>This helper deliberately does not infer a STASH from chat or player
 * proximity. The event adapter must either use
 * {@link #recordInteraction(StashDefinition, int, int, int, int, Action, long)}
 * with the clicked object's world location, or verify that same predicate
 * before calling {@link #recordVerifiedInteraction(String, Action, long)}.
 * It must call {@link #clear()} at logout, profile/account changes, world hops,
 * and on every interaction that is not a matching STASH. Account ownership and
 * state mutation remain with the caller.</p>
 *
 * <p>The success strings are the exact equality checks used by RuneLite's
 * {@code ClueScrollPlugin}; failed and unrelated messages cannot produce an
 * update.</p>
 */
public final class StashInteractionTracker
{
    public static final String DEPOSIT_SUCCESS_MESSAGE = "You deposit your items into the STASH unit.";
    public static final String WITHDRAW_SUCCESS_MESSAGE = "You withdraw your items from the STASH unit.";

    /** The only STASH menu action verified in pinned RuneLite source. */
    public enum Action
    {
        SEARCH
    }

    /** Immutable confirmed contents change for the state owner to apply. */
    public static final class Update
    {
        private final String stashId;
        private final ContentsStatus contentsStatus;

        private Update(String stashId, ContentsStatus contentsStatus)
        {
            this.stashId = stashId;
            this.contentsStatus = contentsStatus;
        }

        public String getStashId()
        {
            return stashId;
        }

        public ContentsStatus getContentsStatus()
        {
            return contentsStatus;
        }
    }

    private final long timeoutTicks;
    private Pending pending;

    public StashInteractionTracker(long timeoutTicks)
    {
        if (timeoutTicks < 0)
        {
            throw new IllegalArgumentException("timeoutTicks must not be negative");
        }
        this.timeoutTicks = timeoutTicks;
    }

    /**
     * Records Search only when the clicked object ID and world location exactly
     * match the supplied catalog definition. A nonmatch cancels older pending
     * state rather than leaving it available for a later chat line.
     */
    public void recordInteraction(StashDefinition definition, int objectId, int x, int y, int plane,
                                  Action action, long tick)
    {
        Objects.requireNonNull(definition, "definition");
        if (definition.getObjectId() != objectId || definition.getWorldPoints().stream().noneMatch(
            point -> point.getX() == x && point.getY() == y && point.getPlane() == plane))
        {
            clear();
            return;
        }
        recordVerifiedInteraction(definition.getId(), action, tick);
    }

    /**
     * Records a Search already verified by an adapter against its catalog
     * object ID and location. A later verified interaction replaces the old
     * pending interaction.
     */
    public void recordVerifiedInteraction(String stashId, Action action, long tick)
    {
        if (stashId == null || stashId.trim().isEmpty())
        {
            throw new IllegalArgumentException("stashId must not be blank");
        }
        pending = new Pending(stashId, Objects.requireNonNull(action, "action"), tick);
    }

    /** Clears pending state at an interaction, logout, profile, or world boundary. */
    public void clear()
    {
        pending = null;
    }

    /**
     * Consumes a pending Search only for either exact core success message.
     * Arbitrary chat leaves a still-valid pending interaction intact; it cannot
     * overwrite contents. A matching success is one-shot.
     */
    public Optional<Update> acceptSuccessMessage(String message, long tick)
    {
        if (pending == null)
        {
            return Optional.empty();
        }
        if (expired(tick))
        {
            clear();
            return Optional.empty();
        }

        ContentsStatus status = statusFor(message);
        if (status == null)
        {
            return Optional.empty();
        }

        String stashId = pending.stashId;
        clear();
        return Optional.of(new Update(stashId, status));
    }

    private boolean expired(long tick)
    {
        return tick < pending.tick || tick - pending.tick > timeoutTicks;
    }

    private static ContentsStatus statusFor(String message)
    {
        if (DEPOSIT_SUCCESS_MESSAGE.equals(message))
        {
            return ContentsStatus.FILLED;
        }
        if (WITHDRAW_SUCCESS_MESSAGE.equals(message))
        {
            return ContentsStatus.EMPTY;
        }
        return null;
    }

    private static final class Pending
    {
        private final String stashId;
        private final Action action;
        private final long tick;

        private Pending(String stashId, Action action, long tick)
        {
            this.stashId = stashId;
            this.action = action;
            this.tick = tick;
        }
    }
}

package com.stashledger.tracking;

import com.stashledger.model.StashDefinition;
import com.stashledger.model.StashTier;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;

/**
 * Parses a fully captured Watson board without changing any account state.
 *
 * <p>Its input adapter owns RuneLite widget access. This parser only accepts a
 * complete, tier-scoped snapshot; callers can therefore leave previous content
 * state intact when the board changed shape or has not finished loading.</p>
 */
public final class WatsonBoardParser
{
    public enum Failure
    {
        NONE, INVALID_INPUT, INVALID_CATALOG, MISSING_TIER, INVALID_ALIASES,
        MALFORMED_ROW, UNKNOWN_LOCATION, DUPLICATE_LOCATION, INCOMPLETE_TIER
    }

    public static final class Result
    {
        private final Failure failure;
        private final StashTier tier;
        private final String diagnostic;
        private final Map<String, Boolean> contents;

        private Result(Failure failure, StashTier tier, String diagnostic, Map<String, Boolean> contents)
        {
            this.failure = failure;
            this.tier = tier;
            this.diagnostic = diagnostic;
            this.contents = contents;
        }

        public Failure getFailure() { return failure; }
        public StashTier getTier() { return tier; }
        public String getDiagnostic() { return diagnostic; }
        public Optional<Map<String, Boolean>> getContents() { return Optional.ofNullable(contents); }
    }

    public static final class Cell
    {
        private final int type;
        private final String text;

        public Cell(int type, String text)
        {
            this.type = type;
            this.text = text;
        }

        public int getType()
        {
            return type;
        }

        public String getText()
        {
            return text;
        }
    }

    private WatsonBoardParser()
    {
    }

    public static Optional<Map<String, Boolean>> parse(
        Map<StashTier, List<Cell>> tiers,
        Map<StashTier, Map<String, String>> aliases,
        List<StashDefinition> definitions)
    {
        return parseDetailed(tiers, aliases, definitions).getContents();
    }

    /** Failed results never expose a partial contents map. */
    public static Result parseDetailed(
        Map<StashTier, List<Cell>> tiers,
        Map<StashTier, Map<String, String>> aliases,
        List<StashDefinition> definitions)
    {
        if (tiers == null || aliases == null || definitions == null)
        {
            return failure(Failure.INVALID_INPUT, null, "Noticeboard data is unavailable.");
        }

        Map<StashTier, Set<String>> idsByTier = idsByTier(definitions);
        if (idsByTier == null)
        {
            return failure(Failure.INVALID_CATALOG, null, "STASH catalog data is invalid.");
        }

        Map<String, Boolean> parsed = new LinkedHashMap<>();
        for (StashTier tier : StashTier.values())
        {
            List<Cell> cells = tiers.get(tier);
            if (cells == null)
            {
                return failure(Failure.MISSING_TIER, tier, tierName(tier) + " tier is not loaded.");
            }
            Map<String, String> tierAliases = normalizedAliases(aliases.get(tier), idsByTier.get(tier));
            if (tierAliases == null)
            {
                return failure(Failure.INVALID_ALIASES, tier, tierName(tier) + " tier aliases are invalid.");
            }

            TierResult tierValues = parseTier(cells, tierAliases, tier);
            if (tierValues.failure != Failure.NONE)
            {
                return failure(tierValues.failure, tier, tierValues.diagnostic);
            }
            if (tierValues.values.size() != idsByTier.get(tier).size()
                || !tierValues.values.keySet().equals(idsByTier.get(tier)))
            {
                return failure(Failure.INCOMPLETE_TIER, tier, tierName(tier) + " tier is incomplete: matched "
                    + tierValues.values.size() + " of " + idsByTier.get(tier).size() + " locations.");
            }
            parsed.putAll(tierValues.values);
        }

        if (parsed.size() != definitions.size())
        {
            return failure(Failure.INVALID_CATALOG, null, "STASH catalog data is inconsistent.");
        }
        return new Result(Failure.NONE, null, "Noticeboard matched.",
            Collections.unmodifiableMap(new LinkedHashMap<>(parsed)));
    }

    /** Normalizes only presentation differences seen in noticeboard labels. */
    public static String normalize(String value)
    {
        if (value == null)
        {
            return "";
        }
        return value.replaceAll("(?i)<br\\s*/?>", " ")
            .replaceAll("<[^>]*>", "")
            // The source board labels include parentheses, e.g. Fishing Guild (Outside).
            // Match the catalog generator's punctuation removal exactly.
            .replaceAll("[^\\p{L}\\p{N}\\s]", "")
            .trim()
            .replaceAll("\\s+", " ")
            .toLowerCase(Locale.ROOT);
    }

    private static Map<StashTier, Set<String>> idsByTier(List<StashDefinition> definitions)
    {
        Map<StashTier, Set<String>> result = new EnumMap<>(StashTier.class);
        for (StashTier tier : StashTier.values())
        {
            result.put(tier, new HashSet<>());
        }
        Set<String> allIds = new HashSet<>();
        for (StashDefinition definition : definitions)
        {
            if (definition == null || definition.getId() == null || definition.getTier() == null || !allIds.add(definition.getId())
                || !result.get(definition.getTier()).add(definition.getId()))
            {
                return null;
            }
        }
        return result;
    }

    private static Map<String, String> normalizedAliases(Map<String, String> aliases, Set<String> validIds)
    {
        if (aliases == null)
        {
            return null;
        }
        Map<String, String> result = new HashMap<>();
        for (Map.Entry<String, String> entry : aliases.entrySet())
        {
            String normalized = normalize(entry.getKey());
            if (normalized.isEmpty() || entry.getValue() == null || !validIds.contains(entry.getValue())
                || result.put(normalized, entry.getValue()) != null)
            {
                return null;
            }
        }
        return result;
    }

    private static TierResult parseTier(List<Cell> cells, Map<String, String> aliases, StashTier tier)
    {
        List<BoardRow> rows = new ArrayList<>();
        String location = null;
        int checks = 0;
        for (Cell cell : cells)
        {
            if (cell == null || (cell.getType() != 4 && cell.getType() != 5))
            {
                return TierResult.failure(Failure.MALFORMED_ROW, tierName(tier) + " tier has an unexpected row.");
            }
            if (cell.getType() == 4)
            {
                if (location != null)
                {
                    rows.add(new BoardRow(location, checks));
                }
                location = normalize(cell.getText());
                if (location.isEmpty())
                {
                    return TierResult.failure(Failure.MALFORMED_ROW, tierName(tier) + " tier has an empty location.");
                }
                checks = 0;
            }
            else
            {
                if (location == null || ++checks > 2)
                {
                    return TierResult.failure(Failure.MALFORMED_ROW, tierName(tier) + " tier has misplaced status markers.");
                }
            }
        }
        if (location == null)
        {
            return TierResult.failure(Failure.MALFORMED_ROW, tierName(tier) + " tier has no locations.");
        }
        rows.add(new BoardRow(location, checks));

        Map<String, Boolean> result = new LinkedHashMap<>();
        for (BoardRow row : rows)
        {
            String id = aliases.get(row.location);
            if (id == null)
            {
                return TierResult.failure(Failure.UNKNOWN_LOCATION, tierName(tier)
                    + " tier has an unknown location: " + bounded(row.location) + ".");
            }
            if (result.put(id, row.checks == 2) != null)
            {
                return TierResult.failure(Failure.DUPLICATE_LOCATION, tierName(tier) + " tier repeats a location.");
            }
        }
        return TierResult.success(result);
    }

    private static Result failure(Failure failure, StashTier tier, String diagnostic)
    {
        return new Result(failure, tier, diagnostic, null);
    }

    private static String bounded(String value)
    {
        return value.length() <= 80 ? value : value.substring(0, 80);
    }

    private static String tierName(StashTier tier)
    {
        String value = tier.name().toLowerCase(Locale.ROOT);
        return Character.toUpperCase(value.charAt(0)) + value.substring(1);
    }

    private static final class TierResult
    {
        private final Failure failure;
        private final String diagnostic;
        private final Map<String, Boolean> values;

        private TierResult(Failure failure, String diagnostic, Map<String, Boolean> values)
        {
            this.failure = failure;
            this.diagnostic = diagnostic;
            this.values = values;
        }

        private static TierResult success(Map<String, Boolean> values)
        {
            return new TierResult(Failure.NONE, "", values);
        }

        private static TierResult failure(Failure failure, String diagnostic)
        {
            return new TierResult(failure, diagnostic, null);
        }
    }

    private static final class BoardRow
    {
        private final String location;
        private final int checks;

        private BoardRow(String location, int checks)
        {
            this.location = location;
            this.checks = checks;
        }
    }
}

