package com.stashledger.state;

import com.stashledger.model.BuildStatus;
import com.stashledger.model.ContentsStatus;
import com.stashledger.model.StashDefinition;
import com.stashledger.model.StashEntry;
import com.stashledger.model.StashTier;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.*;

public class LedgerStateTest
{
    private LedgerState newState()
    {
        return new LedgerState(List.of(
            new StashDefinition("a", 1, "A", StashTier.EASY, 1, 2, 0, List.of("Gold ring")),
            new StashDefinition("b", 2, "B", StashTier.MASTER, 3, 4, 0, List.of("Any full Barrows set"))));
    }

    @Test public void unseenIsUnknownRatherThanNotBuiltOrEmpty()
    {
        LedgerState state = newState();
        for (StashEntry entry : state.snapshot())
        {
            assertEquals(BuildStatus.UNKNOWN, entry.getBuildStatus());
            assertEquals(ContentsStatus.UNKNOWN, entry.getContentsStatus());
        }
    }

    @Test public void onlyBuiltUnitsAcceptContentsConfirmation()
    {
        LedgerState state = newState();
        assertFalse(state.markContents("a", ContentsStatus.FILLED));
        state.applyBuildScan(Map.of("a", BuildStatus.NOT_BUILT, "b", BuildStatus.BUILT));
        assertFalse(state.markContents("a", ContentsStatus.FILLED));
        assertTrue(state.markContents("b", ContentsStatus.EMPTY));
        assertFalse(state.markContents("missing", ContentsStatus.FILLED));
        assertEquals(ContentsStatus.EMPTY, state.snapshot().get(1).getContentsStatus());
    }

    @Test public void savedContentsAndPinsRoundTripWithoutTrustingOldConstruction()
    {
        LedgerState first = newState();
        first.applyBuildScan(Map.of("a", BuildStatus.BUILT));
        first.markContents("a", ContentsStatus.FILLED);
        first.togglePinned("a");
        LedgerState restored = newState();
        restored.load(first.serialize());
        assertEquals(BuildStatus.UNKNOWN, restored.snapshot().get(0).getBuildStatus());
        assertEquals(ContentsStatus.UNKNOWN, restored.snapshot().get(0).getContentsStatus());
        assertTrue(restored.snapshot().get(0).isPinned());
        restored.applyBuildScan(Map.of("a", BuildStatus.BUILT));
        assertEquals(ContentsStatus.FILLED, restored.snapshot().get(0).getContentsStatus());
    }

    @Test public void confirmedUnbuiltClearsContentsButKeepsShortlist()
    {
        LedgerState state = newState();
        state.applyBuildScan(Map.of("a", BuildStatus.BUILT));
        state.markContents("a", ContentsStatus.FILLED);
        state.togglePinned("a");
        state.applyBuildScan(Map.of("a", BuildStatus.NOT_BUILT));
        state.applyBuildScan(Map.of("a", BuildStatus.BUILT));
        assertEquals(ContentsStatus.UNKNOWN, state.snapshot().get(0).getContentsStatus());
        assertTrue(state.snapshot().get(0).isPinned());
    }

    @Test public void unknownScanDoesNotDestroyConfirmedContents()
    {
        LedgerState state = newState();
        state.applyBuildScan(Map.of("a", BuildStatus.BUILT));
        state.markContents("a", ContentsStatus.FILLED);
        state.applyBuildScan(Map.of());
        assertEquals(ContentsStatus.UNKNOWN, state.snapshot().get(0).getContentsStatus());
        state.applyBuildScan(Map.of("a", BuildStatus.BUILT));
        assertEquals(ContentsStatus.FILLED, state.snapshot().get(0).getContentsStatus());
    }

    @Test public void loadingAnotherAccountClearsOldPinsAndContents()
    {
        LedgerState state = newState();
        state.togglePinned("a");
        state.applyBuildScan(Map.of("a", BuildStatus.BUILT));
        state.markContents("a", ContentsStatus.FILLED);
        state.load(null);
        assertFalse(state.snapshot().get(0).isPinned());
        assertEquals(BuildStatus.UNKNOWN, state.snapshot().get(0).getBuildStatus());
        state.applyBuildScan(Map.of("a", BuildStatus.BUILT));
        assertEquals(ContentsStatus.UNKNOWN, state.snapshot().get(0).getContentsStatus());
    }

    @Test public void malformedSaveDoesNotPartiallyReplaceCurrentState()
    {
        LedgerState state = newState();
        state.togglePinned("a");
        String original = state.serialize();
        assertThrows(RuntimeException.class, () -> state.load("{\"version\":1,\"units\":{\"a\":{\"pinned\":false},\"b\":{\"contents\":\"broken\"}}}"));
        assertEquals(original, state.serialize());
        assertThrows(RuntimeException.class, () -> state.load("{\"version\":2,\"units\":{}}"));
        assertEquals(original, state.serialize());
    }

    @Test public void snapshotsAndDefinitionsAreImmutable()
    {
        LedgerState state = newState();
        List<StashEntry> old = state.snapshot();
        state.togglePinned("a");
        assertFalse(old.get(0).isPinned());
        assertThrows(UnsupportedOperationException.class, () -> old.clear());
        assertThrows(UnsupportedOperationException.class, () -> old.get(0).getDefinition().getItems().clear());
    }
}

package com.stashledger.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.stashledger.model.BuildStatus;
import com.stashledger.model.StashDefinition;
import com.stashledger.model.StashTier;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import org.junit.Test;

public class BuildScannerTest
{
    @Test
    public void usesTheWatsonScriptAndTheStackTopForEveryDefinition()
    {
        Client client = mock(Client.class);
        int[] stack = {0, 99};
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getIntStack()).thenReturn(stack);
        doAnswer(invocation ->
        {
            stack[0] = ((int) invocation.getArguments()[1]) == 11 ? 1 : 0;
            return null;
        }).when(client).runScript(eq(ScriptID.WATSON_STASH_UNIT_CHECK), anyInt(), eq(0), eq(0), eq(0));

        List<StashDefinition> definitions = Arrays.asList(definition("one", 11), definition("two", 12));
        Map<String, BuildStatus> result = BuildScanner.scan(client, definitions);

        assertEquals(BuildStatus.BUILT, result.get("one"));
        assertEquals(BuildStatus.NOT_BUILT, result.get("two"));
        verify(client).runScript(ScriptID.WATSON_STASH_UNIT_CHECK, 11, 0, 0, 0);
        verify(client).runScript(ScriptID.WATSON_STASH_UNIT_CHECK, 12, 0, 0, 0);
    }

    @Test
    public void marksUnexpectedScriptValuesUnknown()
    {
        Client client = mock(Client.class);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getIntStack()).thenReturn(new int[]{2});

        assertEquals(BuildStatus.UNKNOWN, BuildScanner.scan(client, Collections.singletonList(definition("one", 11))).get("one"));
    }

    @Test
    public void leavesEveryResultUnknownOutsideLoggedInState()
    {
        Client client = mock(Client.class);
        when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);

        Map<String, BuildStatus> result = BuildScanner.scan(client, Collections.singletonList(definition("one", 11)));

        assertEquals(BuildStatus.UNKNOWN, result.get("one"));
        verify(client, never()).runScript(eq(ScriptID.WATSON_STASH_UNIT_CHECK), anyInt(), anyInt(), anyInt(), anyInt());
    }

    @Test
    public void letsScriptFailuresEscapeBeforeReturningAnySnapshot()
    {
        Client client = mock(Client.class);
        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        doAnswer(invocation -> { throw new IllegalStateException("script failed"); })
            .when(client).runScript(eq(ScriptID.WATSON_STASH_UNIT_CHECK), anyInt(), eq(0), eq(0), eq(0));

        assertThrows(IllegalStateException.class,
            () -> BuildScanner.scan(client, Collections.singletonList(definition("one", 11))));
    }

    private static StashDefinition definition(String id, int objectId)
    {
        return new StashDefinition(id, objectId, id, StashTier.BEGINNER, 0, 0, 0, Collections.emptyList());
    }
}

package com.stashledger.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.stashledger.model.ContentsStatus;
import com.stashledger.model.StashDefinition;
import com.stashledger.model.StashTier;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class StashInteractionTrackerTest
{
    @Test
    public void exactDepositAfterMatchingSearchProducesOneFilledUpdate()
    {
        StashInteractionTracker tracker = new StashInteractionTracker(2);
        tracker.recordInteraction(definition("one", 100, 3200, 3201, 0), 100, 3200, 3201, 0,
            StashInteractionTracker.Action.SEARCH, 40);

        StashInteractionTracker.Update update = tracker
            .acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 42).get();

        assertEquals("one", update.getStashId());
        assertEquals(ContentsStatus.FILLED, update.getContentsStatus());
        assertFalse(tracker.acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 42).isPresent());
    }

    @Test
    public void exactWithdrawAfterMatchingSearchProducesEmptyUpdate()
    {
        StashInteractionTracker tracker = new StashInteractionTracker(2);
        tracker.recordVerifiedInteraction("one", StashInteractionTracker.Action.SEARCH, 40);

        Optional<StashInteractionTracker.Update> update = tracker
            .acceptSuccessMessage(StashInteractionTracker.WITHDRAW_SUCCESS_MESSAGE, 41);

        assertTrue(update.isPresent());
        assertEquals(ContentsStatus.EMPTY, update.get().getContentsStatus());
    }

    @Test
    public void spuriousOrLooselySimilarMessagesCannotChangeContents()
    {
        StashInteractionTracker tracker = new StashInteractionTracker(2);
        tracker.recordVerifiedInteraction("one", StashInteractionTracker.Action.SEARCH, 40);

        assertFalse(tracker.acceptSuccessMessage("You filled the STASH unit.", 41).isPresent());
        assertFalse(tracker.acceptSuccessMessage("You deposit your items into the stash unit.", 41).isPresent());
        assertFalse(tracker.acceptSuccessMessage("You deposit your items into the STASH unit.", 43).isPresent());
    }

    @Test
    public void expiredPendingSearchCannotApplyAnOtherwiseExactSuccessMessage()
    {
        StashInteractionTracker tracker = new StashInteractionTracker(1);
        tracker.recordVerifiedInteraction("one", StashInteractionTracker.Action.SEARCH, 40);

        assertFalse(tracker.acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 42).isPresent());
        assertFalse(tracker.acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 42).isPresent());
    }

    @Test
    public void wrongObjectOrLocationCancelsTheEarlierPendingSearch()
    {
        StashInteractionTracker tracker = new StashInteractionTracker(2);
        StashDefinition definition = definition("one", 100, 3200, 3201, 0);
        tracker.recordVerifiedInteraction("other", StashInteractionTracker.Action.SEARCH, 40);

        tracker.recordInteraction(definition, 101, 3200, 3201, 0, StashInteractionTracker.Action.SEARCH, 41);
        assertFalse(tracker.acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 41).isPresent());

        tracker.recordVerifiedInteraction("other", StashInteractionTracker.Action.SEARCH, 42);
        tracker.recordInteraction(definition, 100, 3201, 3201, 0, StashInteractionTracker.Action.SEARCH, 42);
        assertFalse(tracker.acceptSuccessMessage(StashInteractionTracker.WITHDRAW_SUCCESS_MESSAGE, 42).isPresent());
    }

    @Test
    public void laterMatchingSearchReplacesEarlierOne()
    {
        StashInteractionTracker tracker = new StashInteractionTracker(2);
        tracker.recordVerifiedInteraction("one", StashInteractionTracker.Action.SEARCH, 40);
        tracker.recordVerifiedInteraction("two", StashInteractionTracker.Action.SEARCH, 41);

        StashInteractionTracker.Update update = tracker
            .acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 42).get();

        assertEquals("two", update.getStashId());
    }

    @Test
    public void profileOrWorldBoundaryClearPreventsCrossAccountApplication()
    {
        StashInteractionTracker tracker = new StashInteractionTracker(2);
        tracker.recordVerifiedInteraction("one", StashInteractionTracker.Action.SEARCH, 40);

        tracker.clear();

        assertFalse(tracker.acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 40).isPresent());
    }

    @Test
    public void matchesAlternateCoordinatesWithoutAcceptingWrongPlaneOrObject()
    {
        StashDefinition definition = new StashDefinition("one", 100, "one", StashTier.MEDIUM,
            List.of(new WorldPoint(3222, 9584, 0), new WorldPoint(3167, 9570, 0)), List.of());
        StashInteractionTracker tracker = new StashInteractionTracker(2);
        tracker.recordInteraction(definition, 100, 3167, 9570, 0, StashInteractionTracker.Action.SEARCH, 40);
        StashInteractionTracker.Update update = tracker
            .acceptSuccessMessage(StashInteractionTracker.WITHDRAW_SUCCESS_MESSAGE, 41).get();
        assertEquals("one", update.getStashId());
        assertEquals(ContentsStatus.EMPTY, update.getContentsStatus());
        tracker.recordInteraction(definition, 100, 3167, 9570, 1, StashInteractionTracker.Action.SEARCH, 42);
        assertFalse(tracker.acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 42).isPresent());
        tracker.recordInteraction(definition, 101, 3167, 9570, 0, StashInteractionTracker.Action.SEARCH, 42);
        assertFalse(tracker.acceptSuccessMessage(StashInteractionTracker.DEPOSIT_SUCCESS_MESSAGE, 42).isPresent());
    }

    private static StashDefinition definition(String id, int objectId, int x, int y, int plane)
    {
        return new StashDefinition(id, objectId, id, StashTier.BEGINNER, x, y, plane, Collections.emptyList());
    }
}

package com.stashledger.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.stashledger.model.StashDefinition;
import com.stashledger.model.StashTier;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import org.junit.Test;

public class WatsonBoardParserTest
{
    @Test
    public void acceptsCompleteSixTierBoardWithTwoOneAndZeroTicks()
    {
        List<StashDefinition> definitions = definitions();
        Map<StashTier, List<WatsonBoardParser.Cell>> board = completeBoard(definitions);

        Optional<Map<String, Boolean>> result = WatsonBoardParser.parse(board, aliases(definitions), definitions);

        assertTrue(result.isPresent());
        assertTrue(result.get().get("beginner"));
        assertFalse(result.get().get("easy"));
        assertFalse(result.get().get("medium"));
        assertTrue(result.get().get("hard"));
    }

    @Test
    public void rejectsUnknownDuplicatePartialAndMalformedBoardRows()
    {
        List<StashDefinition> definitions = definitions();
        Map<StashTier, List<WatsonBoardParser.Cell>> unknown = completeBoard(definitions);
        unknown.put(StashTier.BEGINNER, Collections.singletonList(cell(4, "not in catalog")));
        assertFalse(WatsonBoardParser.parse(unknown, aliases(definitions), definitions).isPresent());

        Map<StashTier, List<WatsonBoardParser.Cell>> duplicate = completeBoard(definitions);
        duplicate.put(StashTier.BEGINNER, Arrays.asList(cell(4, "Beginner place"), cell(4, "Beginner place")));
        assertFalse(WatsonBoardParser.parse(duplicate, aliases(definitions), definitions).isPresent());

        Map<StashTier, List<WatsonBoardParser.Cell>> partial = completeBoard(definitions);
        partial.remove(StashTier.MASTER);
        assertFalse(WatsonBoardParser.parse(partial, aliases(definitions), definitions).isPresent());

        Map<StashTier, List<WatsonBoardParser.Cell>> malformed = completeBoard(definitions);
        malformed.put(StashTier.ELITE, Arrays.asList(cell(4, "Elite place"), cell(5, null), cell(5, null), cell(5, null)));
        assertFalse(WatsonBoardParser.parse(malformed, aliases(definitions), definitions).isPresent());
    }

    @Test
    public void normalizesPresentationTagsPunctuationAndWhitespace()
    {
        assertEquals("warriors guild bank", WatsonBoardParser.normalize(" <col=ff00ff>Warriors’ Guild - bank</col> "));
        assertEquals("warriorsguild", WatsonBoardParser.normalize("Warriors’_Guild"));
    }

    @Test
    public void normalizesKnownLineBreakMarkupWithoutJoiningLocationWords()
    {
        assertEquals("centre of canifis", WatsonBoardParser.normalize("Centre of<br>Canifis"));
        assertEquals("centre of canifis", WatsonBoardParser.normalize("Centre of<BR />Canifis"));
        assertEquals("centre of canifis", WatsonBoardParser.normalize("<col=ff00ff>Centre of</col><br/>Canifis"));
        assertEquals("centre ofcanifis", WatsonBoardParser.normalize("Centre of<col=ff00ff>Canifis</col>"));
    }

    @Test
    public void detailedParsePreservesLegacySuccessAndReturnsAnImmutableSnapshot()
    {
        List<StashDefinition> definitions = definitions();
        Map<StashTier, List<WatsonBoardParser.Cell>> board = completeBoard(definitions);

        WatsonBoardParser.Result detailed = WatsonBoardParser.parseDetailed(board, aliases(definitions), definitions);

        assertEquals(WatsonBoardParser.Failure.NONE, detailed.getFailure());
        assertNull(detailed.getTier());
        assertTrue(detailed.getContents().isPresent());
        assertEquals(WatsonBoardParser.parse(board, aliases(definitions), definitions), detailed.getContents());
        try
        {
            detailed.getContents().get().put("new", true);
            throw new AssertionError("Successful snapshots must be immutable");
        }
        catch (UnsupportedOperationException expected)
        {
            // The parser owns the immutable complete snapshot used by the account state update.
        }
    }

    @Test
    public void detailedParseKeepsFailuresFailClosedAndTierScoped()
    {
        List<StashDefinition> definitions = definitions();

        Map<StashTier, List<WatsonBoardParser.Cell>> unknown = completeBoard(definitions);
        unknown.put(StashTier.BEGINNER, Collections.singletonList(cell(4, "not in catalog")));
        assertFailure(unknown, definitions, WatsonBoardParser.Failure.UNKNOWN_LOCATION, StashTier.BEGINNER);

        Map<StashTier, List<WatsonBoardParser.Cell>> duplicate = completeBoard(definitions);
        duplicate.put(StashTier.EASY, Arrays.asList(cell(4, "Easy place"), cell(4, "Easy place")));
        assertFailure(duplicate, definitions, WatsonBoardParser.Failure.DUPLICATE_LOCATION, StashTier.EASY);

        Map<StashTier, List<WatsonBoardParser.Cell>> malformed = completeBoard(definitions);
        malformed.put(StashTier.ELITE, Arrays.asList(cell(4, "Elite place"), cell(5, null), cell(5, null), cell(5, null)));
        assertFailure(malformed, definitions, WatsonBoardParser.Failure.MALFORMED_ROW, StashTier.ELITE);

        Map<StashTier, List<WatsonBoardParser.Cell>> missing = completeBoard(definitions);
        missing.remove(StashTier.MASTER);
        assertFailure(missing, definitions, WatsonBoardParser.Failure.MISSING_TIER, StashTier.MASTER);

        List<StashDefinition> incompleteDefinitions = new ArrayList<>(definitions);
        incompleteDefinitions.add(new StashDefinition("beginner-second", 99, "Beginner second", StashTier.BEGINNER,
            0, 0, 0, Collections.emptyList()));
        Map<StashTier, Map<String, String>> incompleteAliases = aliases(incompleteDefinitions);
        Map<StashTier, List<WatsonBoardParser.Cell>> incomplete = completeBoard(definitions);
        WatsonBoardParser.Result result = WatsonBoardParser.parseDetailed(incomplete, incompleteAliases, incompleteDefinitions);
        assertEquals(WatsonBoardParser.Failure.INCOMPLETE_TIER, result.getFailure());
        assertEquals(StashTier.BEGINNER, result.getTier());
        assertFalse(result.getContents().isPresent());
        assertTrue(result.getDiagnostic().toLowerCase(Locale.ROOT).contains("beginner"));
        assertTrue(result.getDiagnostic().contains("1"));
        assertTrue(result.getDiagnostic().contains("2"));
    }

    @Test
    public void detailedUnknownDiagnosticIsSanitizedAndBounded()
    {
        List<StashDefinition> definitions = definitions();
        String untrusted = "<col=ff00ff>Private\n" + String.join("", Collections.nCopies(200, "x")) + "</col>";
        Map<StashTier, List<WatsonBoardParser.Cell>> board = completeBoard(definitions);
        board.put(StashTier.HARD, Collections.singletonList(cell(4, untrusted)));

        WatsonBoardParser.Result result = WatsonBoardParser.parseDetailed(board, aliases(definitions), definitions);

        assertEquals(WatsonBoardParser.Failure.UNKNOWN_LOCATION, result.getFailure());
        assertEquals(StashTier.HARD, result.getTier());
        assertFalse(result.getContents().isPresent());
        assertFalse(result.getDiagnostic().contains("<col="));
        assertFalse(result.getDiagnostic().contains("\n"));
        assertTrue("Diagnostic must not echo an unbounded widget string", result.getDiagnostic().length() <= 200);
    }

    private static void assertFailure(Map<StashTier, List<WatsonBoardParser.Cell>> board,
        List<StashDefinition> definitions, WatsonBoardParser.Failure expected, StashTier tier)
    {
        WatsonBoardParser.Result result = WatsonBoardParser.parseDetailed(board, aliases(definitions), definitions);
        assertEquals(expected, result.getFailure());
        assertEquals(tier, result.getTier());
        assertFalse(result.getContents().isPresent());
        assertTrue("Diagnostics should explain the failing tier",
            result.getDiagnostic().toLowerCase(Locale.ROOT).contains(tier.name().toLowerCase(Locale.ROOT)));
    }

    private static Map<StashTier, List<WatsonBoardParser.Cell>> completeBoard(List<StashDefinition> definitions)
    {
        Map<StashTier, List<WatsonBoardParser.Cell>> board = new EnumMap<>(StashTier.class);
        for (StashDefinition definition : definitions)
        {
            List<WatsonBoardParser.Cell> cells = new ArrayList<>();
            cells.add(cell(4, definition.getName()));
            if (definition.getTier() == StashTier.BEGINNER || definition.getTier() == StashTier.HARD)
            {
                cells.add(cell(5, null));
                cells.add(cell(5, null));
            }
            else if (definition.getTier() == StashTier.EASY)
            {
                cells.add(cell(5, null));
            }
            board.put(definition.getTier(), cells);
        }
        return board;
    }

    private static Map<StashTier, Map<String, String>> aliases(List<StashDefinition> definitions)
    {
        Map<StashTier, Map<String, String>> result = new EnumMap<>(StashTier.class);
        for (StashDefinition definition : definitions)
        {
            result.computeIfAbsent(definition.getTier(), ignored -> new java.util.LinkedHashMap<>())
                .put(definition.getName(), definition.getId());
        }
        return result;
    }

    private static List<StashDefinition> definitions()
    {
        List<StashDefinition> definitions = new ArrayList<>();
        for (StashTier tier : StashTier.values())
        {
            String id = tier.name().toLowerCase();
            definitions.add(new StashDefinition(id, tier.ordinal() + 1, title(tier) + " place", tier, 0, 0, 0, Collections.emptyList()));
        }
        return definitions;
    }

    private static String title(StashTier tier)
    {
        return tier.name().substring(0, 1) + tier.name().substring(1).toLowerCase();
    }

    private static WatsonBoardParser.Cell cell(int type, String text)
    {
        return new WatsonBoardParser.Cell(type, text);
    }
}

